L(OA, 5,
  "Aprenderé a situar un texto no literario en su contexto de producción (autor, fecha, propósito, fiabilidad) y a decidir si sirve para contextualizar una obra.",
  ["Contrasto interpretaciones con evidencia.", "Reconozco datos y opiniones."],
  ["No todos los textos no literarios sirven igual. Antes de usar uno para contextualizar una obra, conviene revisar quién lo escribió, cuándo, para qué y dónde se publicó. Una enciclopedia o una nota de un historiador suele ser más fiable que un mensaje sin autor. Un texto antiguo puede estar desactualizado.",
   "También hay que ver la pertinencia: ¿habla del mismo lugar, época y tema que la obra? Una nota sobre pescadores del sur no sirve para contextualizar un poema sobre una estación de trenes del norte. Además, hay que mirar el propósito: una reseña opina, una biografía informa, un folleto turístico busca atraer visitantes y puede destacar solo lo agradable.",
   "Un buen criterio combina fiabilidad y pertinencia. Si la fuente es fiable y pertinente, se usa. Si es pertinente pero poco fiable, se busca una segunda fuente. Si es fiable pero no pertinente, se descarta para ese fin. Conviene registrar la fuente: autor, título, fecha y lugar de publicación, para poder volver a ella."],
  [("fiabilidad", "grado en que se puede confiar en una fuente"), ("pertinencia", "relación directa con el tema y la obra"), ("desactualizado", "que ya no refleja la información más reciente"), ("registro de fuente", "anotación de autor, título, fecha y lugar de publicación")],
  [("Fiabilidad y pertinencia",
    "Para contextualizar un cuento sobre un pueblo ferroviario, tienes: (a) una nota histórica de un archivo sobre el ramal, firmada por un historiador; (b) un mensaje anónimo en un chat sobre trenes. ¿Cuál es más fiable?",
    ["La nota tiene autor y archivo.", "El mensaje no tiene autor.", "La nota es más fiable."],
    "La nota histórica firmada"),
   ("Descartar por falta de pertinencia",
    "Para un poema sobre un faro del sur, ¿sirve una nota sobre trenes del norte?",
    ["Es una fuente tal vez fiable.", "Pero trata otro lugar y tema.", "No es pertinente."],
    "No, porque no es pertinente")],
  [("Usar una fuente porque es la primera que aparece.", "Ser primero no la hace fiable.", "Revisa autor, fecha y propósito."),
   ("Descartar una fuente solo por ser antigua.", "Puede seguir siendo válida.", "Comprueba si la información cambió.")],
  ([E("¿Qué es la fiabilidad de una fuente?", "El grado en que se puede confiar en ella", "Depende de autor, método y origen."),
    E("¿Qué es la pertinencia?", "Que se relaciona con el tema y la obra", "Una fuente pertinente aporta al caso."),
    E("¿Qué se anota en un registro de fuente: autor, título y fecha, o solo el color?", "Autor, título y fecha", "Permite volver a ella.")],
   [E("Quieres contextualizar un poema sobre un faro. Tienes una nota de un historiador sobre faros y un folleto de turismo del mismo faro. ¿Cuál tiene más riesgo de mostrar solo lo agradable? A) el folleto B) la nota del historiador", "A) el folleto", "Su propósito es atraer visitantes."),
    E("Una nota fue escrita en 1950 sobre la población de un pueblo y el poema trata de 2010. ¿Qué riesgo hay? A) estar desactualizada B) ser demasiado nueva", "A) estar desactualizada", "Puede no reflejar la situación posterior."),
    E("Un texto no trae autor ni fecha. ¿Cuál de estas ausencias impide más saber quién respalda lo que dice? A) la falta de autor B) la falta de fecha", "A) la falta de autor", "Sin autor no se sabe quién responde por el texto; la fecha ayuda a ver si está desactualizado.")],
   [E("Clasifica cada fuente como F (fiable) o D (dudosa): 1) enciclopedia con autor y fecha. 2) cadena de mensajes sin autor. 3) artículo de un archivo histórico con firma. Escribe las letras en orden.", "F, D, F", "Las fuentes con autor, fecha o institución se pueden verificar."),
    E("Para un cuento sobre una escuela rural, ¿qué fuente es pertinente? A) una nota sobre la matrícula en escuelas rurales B) un texto sobre autos de carrera", "A) una nota sobre la matrícula en escuelas rurales", "Se relaciona con el tema."),
    E("Fuente de ejemplo: nota de 2020 que dice que el ramal cerró en 1975. Otra nota de 2021 dice que cerró en 1976. ¿Qué haces? A) buscar una tercera fuente B) elegir al azar", "A) buscar una tercera fuente", "Hay una discrepancia que debe resolverse.")],
   [E("Un compañero usa un folleto turístico para describir la vida real de un pueblo. ¿Qué observación le haces? A) el folleto busca atraer visitantes y puede omitir lo negativo B) el folleto es más fiable que la nota de un historiador porque es más vistoso", "A) el folleto busca atraer visitantes y puede omitir lo negativo", "Su propósito condiciona el contenido; lo vistoso no lo hace más fiable."),
    E("Una fuente es fiable pero no pertinente. ¿La usas para el fin de la obra: sí o no?", "No", "No se relaciona con la obra.")],
   [E("Registro de ejemplo: «Nota histórica sobre el ramal, 2012». Según la definición de registro de fuente, ¿qué dos datos faltan? A) autor y lugar de publicación B) número de páginas y precio", "A) autor y lugar de publicación", "El registro lleva autor, título, fecha y lugar de publicación; aquí ya están el título y la fecha."),
    E("Tienes tres fuentes sobre el cierre del ramal: archivo (1975), mensaje anónimo y una reseña de 2018. Para un dato histórico exacto, ¿cuál es la mejor primera opción?", "El archivo", "Es una fuente institucional con respaldo.")]),
  [E("Quieres contextualizar un poema sobre una caleta. Una nota de un geógrafo explica cómo viven las caletas y otra es un anuncio de vacaciones. ¿Cuál eliges? A) la del geógrafo B) el anuncio", "A) la del geógrafo", "Tiene un propósito informativo y un autor especialista.")],
  [E("¿Qué se revisa antes de usar una fuente?", "Autor, fecha y propósito", "Sirve para decidir su fiabilidad."),
   E("¿Una fuente puede ser fiable pero no pertinente?", "Sí", "Puede ser seria pero hablar de otro tema."),
   E("¿Qué es una fuente desactualizada?", "Una que ya no refleja la información reciente", "Puede haber cambios posteriores.")],
  ("Tienes estas fuentes de ejemplo para entender un cuento sobre una escuela de un pueblo que se vació: (a) nota de un investigador de educación rural con fecha; (b) mensaje sin autor; (c) folleto turístico del pueblo. Evalúa cada una (fiabilidad y pertinencia) y decide cuál usar y cuál no.",
   "(a) Fiable y pertinente: la uso. (b) No fiable: la descarto. (c) Su propósito es atraer visitantes y no habla de la escuela: no la uso.",
   ["evalúa las tres fuentes", "usa fiabilidad y pertinencia", "decide con una razón"], ["tres evaluaciones y una decisión"], ["decidir sin razones"], "Comprueba que cada decisión mencione fiabilidad o pertinencia."),
  "Escribe el registro de una fuente que uses en casa: autor, título, fecha y lugar.",
  "Escribe tres criterios para decidir si una nota sirve para contextualizar un poema.")
